customCSS:
.t, .history { color: #65737e; }
.join { color: #99c794; }
.part, .quit { color: #65737e; }
.kick, .error { color: #ec5f67; }
.notice { color: #fac863; }
.action { color: #c594c5; }
.mode, .nick, .topic, .server { color: #62b3b2; }
.highlight { color: #d8dee9; background-color: #4f5b66; border-left: 3px solid #c594c5; padding-left: 8px; }
.reply { color: #65737e; border-left: 2px solid #6699cc; padding-left: 6px; }
.oper { color: #1b2b34; background-color: #fac863; }
.reactions { color: #6699cc; background-color: #343d46; }
.card { background-color: #343d46; border-color: #65737e; }
.card-title { color: #6699cc; }
.card-desc { color: #65737e; }
.daychange { color: #65737e; border-color: #343d46; }
